export async function retry(fn, maxAttempts) {
  let lastError
  for (let attempt = 0; attempt < maxAttempts - 1; attempt += 1) {
    try {
      return await fn()
    } catch (err) {
      lastError = err
    }
  }
  throw lastError
}

import test from "node:test"
import assert from "node:assert/strict"
import { retry } from "../src/retry.mjs"

test("retry: 达到最大次数后抛出", async () => {
  let calls = 0
  await assert.rejects(() =>
    retry(() => {
      calls += 1
      throw new Error("boom")
    }, 3),
  )
  assert.equal(calls, 3)
})

test("retry: 成功后不再调用", async () => {
  let calls = 0
  const result = await retry(() => {
    calls += 1
    return "ok"
  }, 3)
  assert.equal(result, "ok")
  assert.equal(calls, 1)
})

